    "shortlink.redirect.follow": {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description The link's short code, optionally suffixed with a literal `+` to request the preview page
                 *     instead of (or, for the QR route, in addition to gating on) the redirect/image. Any shape
                 *     that does not match a real code, once the optional `+` is stripped, is treated as an
                 *     unknown link (`404`), not a validation error — this parameter intentionally accepts any
                 *     short string rather than the strict code pattern.
                 */
                code: components["parameters"]["PublicCodeParam"];
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Preview page (preview branch — code ends with `+`). */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/html": string;
                };
            };
            /** @description Permanent redirect (redirect branch, link's `permanent` is true). Empty body. */
            301: {
                headers: {
                    /** @description The link's target URL. */
                    Location?: string;
                    "Cache-Control"?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Temporary redirect (redirect branch, link's `permanent` is false). Empty body. */
            302: {
                headers: {
                    /** @description The link's target URL. */
                    Location?: string;
                    "Cache-Control"?: string;
                    [name: string]: unknown;
                };
                content?: never;
            };
            404: components["responses"]["LinkNotFound"];
            /** @description Link exists but is not active (redirect branch only — the preview branch never returns this). See `LinkGone`. */
            410: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorEnvelope"];
                };
            };
            429: components["responses"]["RateLimited"];
        };
    };
